#nullable enable // autogenerated

using MVZ2.Audios;
using MVZ2.Resources;
using MVZ2Logic.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public class ResourceLibrary
    {
        public void Init()
        {
            spriteResolver.AddProvider(baseGameSprites);
            textureResolver.AddProvider(baseGameTextures);
            audioClipResolver.AddProvider(baseGameAudioClips);
        }
        public void Clear()
        {
            baseGameSprites.Clear();
            baseGameTextures.Clear();
            baseGameAudioClips.Clear();
        }

        #region Provider
        public void AddSpriteProvider(ISpriteProvider provider) => spriteResolver.AddProvider(provider);
        public void RemoveSpriteProvider(ISpriteProvider provider) => spriteResolver.RemoveProvider(provider);
        public void AddTextureProvider(ITexture2DProvider provider) => textureResolver.AddProvider(provider);
        public void RemoveTextureProvider(ITexture2DProvider provider) => textureResolver.RemoveProvider(provider);
        public void AddAudioClipProvider(IAudioClipProvider provider) => audioClipResolver.AddProvider(provider);
        public void RemoveAudioClipProvider(IAudioClipProvider provider) => audioClipResolver.RemoveProvider(provider);
        public void AddSoundMetaProvider(ISoundMetaProvider provider) => soundMetaResolver.AddProvider(provider);
        public void RemoveSoundMetaProvider(ISoundMetaProvider provider) => soundMetaResolver.RemoveProvider(provider);
        #endregion

        #region register
        public void RegisterSprite(SpriteLookupKey key, Sprite value)
        {
            baseGameSprites.Register(key, value);
        }
        public void RegisterTexture2D(NamespaceID key, Texture2D value)
        {
            baseGameTextures.Register(key, value);
        }
        public void RegisterAudioClip(NamespaceID key, AudioClip value)
        {
            baseGameAudioClips.Register(key, value);
        }
        #endregion

        #region 获取
        public Sprite? GetSprite(SpriteReference? spriteRef)
        {
            if (!SpriteReference.IsValid(spriteRef))
                return null;
            var spriteLookupKey = new SpriteLookupKey(spriteRef);
            return baseGameSprites.TryGet(spriteLookupKey, out var value) ? value : null;
        }
        public Texture2D? GetTexture2D(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return baseGameTextures.TryGet(id, out var value) ? value : null;
        }
        public AudioClip? GetAudioClip(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return baseGameAudioClips.TryGet(id, out var value) ? value : null;
        }
        #endregion

        #region 获取最终资源
        public Sprite GetFinalSprite(Sprite sprite, ResourceContext context)
        {
            var spriteRef = GetSpriteReference(sprite);
            return GetFinalSprite(spriteRef, context) ?? sprite;
        }
        public Sprite? GetFinalSprite(SpriteReference? spriteRef, ResourceContext context)
        {
            if (!SpriteReference.IsValid(spriteRef))
                return null;
            var key = new SpriteLookupKey(spriteRef);
            return GetFinalSprite(key, context);
        }
        public Sprite? GetFinalSprite(SpriteLookupKey key, ResourceContext context)
        {
            return spriteResolver.Resolve(key, context);
        }
        public Texture2D GetFinalTexture(Texture2D texture2D, ResourceContext args)
        {
            var id = GetTexture2DID(texture2D);
            return GetFinalTexture(id, args) ?? texture2D;
        }
        public Texture2D? GetFinalTexture(NamespaceID? id, ResourceContext context)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return textureResolver.Resolve(id, context);
        }
        public AudioClip GetFinalAudioClip(AudioClip audioClip, ResourceContext args)
        {
            var id = GetAudioClipID(audioClip);
            return GetFinalAudioClip(id, args) ?? audioClip;
        }
        public AudioClip? GetFinalAudioClip(NamespaceID? id, ResourceContext context)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return audioClipResolver.Resolve(id, context);
        }
        public ISoundMeta? GetFinalSoundMeta(NamespaceID? id, ResourceContext context)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            return soundMetaResolver.Resolve(id, context);
        }
        #endregion

        #region ID
        public SpriteReference? GetSpriteReference(Sprite sprite)
        {
            return baseGameSprites.GetKey(sprite)?.reference;
        }
        public NamespaceID? GetTexture2DID(Texture2D texture2D)
        {
            return baseGameTextures.GetKey(texture2D);
        }
        public NamespaceID? GetAudioClipID(AudioClip clip)
        {
            return baseGameAudioClips.GetKey(clip);
        }
        #endregion
        private ResourceDatabase<SpriteLookupKey, Sprite> baseGameSprites = new ResourceDatabase<SpriteLookupKey, Sprite>();
        private ResourceDatabase<NamespaceID, Texture2D> baseGameTextures = new ResourceDatabase<NamespaceID, Texture2D>();
        private ResourceDatabase<NamespaceID, AudioClip> baseGameAudioClips = new ResourceDatabase<NamespaceID, AudioClip>();

        private SpriteResourceResolver spriteResolver = new SpriteResourceResolver();
        private ResourceResolver<NamespaceID, Texture2D> textureResolver = new ResourceResolver<NamespaceID, Texture2D>();
        private ResourceResolver<NamespaceID, AudioClip> audioClipResolver = new ResourceResolver<NamespaceID, AudioClip>();
        private ResourceResolver<NamespaceID, ISoundMeta> soundMetaResolver = new ResourceResolver<NamespaceID, ISoundMeta>();
    }
}
